    "Наставник + инструктор": "Mentor + instructor",
    "Спорт": "Sports",
    "В лагере организовано пятиразовое питание:": "The camp provides five meals a day:",
    "Снек": "Snack",
    "Пожалуйста не давайте в лагерь сладкое. Ваших детей ждет сбалансированное 5-ти разовое питание и отличная программа.":
      "Please do not send sweets to camp. Your children will enjoy balanced 5-meal nutrition and an excellent program.",
    "Летний домик на 10 мест": "Summer cabin for 10 people",
    "Вместе с группой и наставником": "Together with the group and mentor",
    "Мы гибко подходим к пожеланиям по расселению и распределению по группам - это можно указать в форме регистрации. Мы помогаем детям завести новые знакомства и развить дружбу. Распределение и компоновку групп мы делаем по возрасту.":
      "We are flexible about accommodation and group assignment preferences - this can be specified in the registration form. We help children make new friends and develop friendships. Group assignment and composition is done by age.",
