    "О программе Маранафа": "About the Maranatha Program",
    "Маранафа - это серия тематических мероприятий, которые проводятся с 1998 года. Каждое мероприятие исследует различные темы или истории, предоставляя участникам уникальный опыт от библейских повествований до фантастических миров.":
      "Maranatha is a series of themed events that have been held since 1998. Each event explores different themes or stories, providing participants with a unique experience from biblical narratives to fantasy worlds.",
    "Коллекция видео с предыдущих сезонов лагеря, интервью и особых моментов.":
      "A collection of videos from previous camp seasons, interviews, and special moments.",
