    "Проект назван в честь Розето, Пенсильвания — городка, где сила общины заменяла лекарства.": "The project is named after Roseto, Pennsylvania — a town where the power of community replaced medicine.",
    "Стать участником Rosetto": "Become a Rosetto member",
    "Зарегистрируйтесь и мы расскажем подробности. Проект основан на доверии — поэтому первый шаг это личный контакт.": "Register and we will share the details. The project is built on trust — so the first step is personal contact.",
