      "Mūsu komanda izskatīs jūsu pieteikumu un sazināsies ar jums tuvākajā laikā. Kamēr gaidāt, varat iepazīties ar informāciju vecākiem.",
    "Указание в форме регистрации если есть ли прививка от энцефалита - необходимо, чтобы знать как действовать в редком случае":
      "Norādīšana reģistrācijas veidlapā, vai ir encefalīta vakcinācija — tas nepieciešams, lai zinātu, kā rīkoties retos gadījumos",
    "Какой пример посвящения и дружбы мы можем взять у Иисуса Христа?":
      "Kādu uzupurēšanās un draudzības piemēru varam smelties no Jēzus Kristus?",
    "Каждый год мы готовим отдельную легенду и прорабатываем все до мелочей. Мы вкладываем всё самое лучшее во время этой недели.":
      "Katru gadu mēs sagatavojam atsevišķu tēmu un izstrādājam visu līdz sīkumiem. Mēs ieguldām visu labāko šajā nedēļā.",
