    "В этом видео вы можете увидеть, как проходят встречи в нашем лагере, познакомиться с нашими сотрудниками и узнать больше о духе и атмосфере Маранафы.":
      "Šajā video jūs varat redzēt, kā norit tikšanās mūsu nometnē, iepazīties ar mūsu darbiniekiem un uzzināt vairāk par Maranafas garu un atmosfēru.",
    "Приведение в лагерь потенциально опасных вещей: ножи, зажигалки, спички, игральные карты, алкоголь, сигареты, вейпы, наркотические и химические вещества, энергетические напитки, любые лекарства без согласования с директором":
      "Potenciāli bīstamu priekšmetu atvešana uz nometni: naži, šķiltavas, sērkociņi, spēļu kārtis, alkohols, cigaretes, veipi, narkotiskās un ķīmiskās vielas, enerģijas dzērieni, jebkuras zāles bez saskaņošanas ar direktoru",
    "Почему важно уважать и слушать родителей?": "Kāpēc ir svarīgi cienīt vecākus un viņiem klausīt?",
    "Пожалуйста не давайте в лагерь сладкое. Ваших детей ждет сбалансированное 5-ти разовое питание (завтрак, обед, полдник, ужин, снек) и отличная программа.":
      "Lūdzu, nedodiet līdzi nometnē saldumus. Jūsu bērnus gaida sabalansēta 5 reižu ēdināšana (brokastis, pusdienas, launags, vakariņas, uzkoda) un lieliska programma.",
    "В домике с девочками - находится и спит наставник женщина.":
      "Mājiņā ar meitenēm atrodas un guļ sieviete-audzinātāja.",
    "В домике с мальчиками - находится и спит наставник мужчина.":
      "Mājiņā ar zēniem atrodas un guļ vīrietis-audzinātājs.",
    "О том что Библия - это собрание из 66 книг, написанное разными людьми об одном Боге на протяжении 1600 лет":
      "Par to, ka Bībele ir 66 grāmatu krājums, ko dažādi cilvēki rakstījuši par vienu Dievu 1600 gadu garumā",
    "Смотреть за своей гигиеной - принимать душ, менять белье":
      "Rūpēties par savu higiēnu — mazgāties dušā, mainīt veļu",
    "Мы работаем над развитием характера, чтобы вырастить добрых, уверенных, радостных, благодарных, посвященных людей.":
      "Mēs strādājam pie rakstura attīstības, lai izaudzinātu laipnus, pārliecinātus, priecīgus, pateicīgus un uzupurīgus cilvēkus.",
    "Лагерь расположен в живописном месте, окруженном лесом. Дети проводят много времени на свежем воздухе, участвуя в различных мероприятиях и наслаждаясь красотой природы.":
      "Nometne atrodas gleznainā vietā, ko ieskauj mežs. Bērni pavada daudz laika svaigā gaisā, piedaloties dažādos pasākumos un baudot dabas skaistumu.",
    "Использование инвентаря или инфраструктуры (бассейн, батут, лазилки, рации) без особого разрешения или не в специально отведенное для этого время":
      "Inventāra vai infrastruktūras (baseins, batuts, kāpšanas iekārtas, rācijas) izmantošana bez īpašas atļaujas vai ārpus tam paredzētā laika",
    "Ношение одежды с изображением неприличных/матных выражений, жестов или картинок":
      "Apģērba valkāšana ar nepiedienīgu/rupju izteicienu, žestu vai attēlu atveidojumiem",
    "Как быть хорошим другом / подругой?": "Kā būt labam draugam / draudzenei?",
    "Расположение по домикам начинается c 14:00": "Izvietošana mājiņās sākas no 14:00",
    "Откуда пошли люди - история сотворения мира": "No kurienes cēlušies cilvēki — pasaules radīšanas stāsts",
    "Когда наставник отлучается - его заменяет помощник.": "Kad audzinātājs aiziet — viņu aizvieto palīgs.",
    "Отдельная команда сделает что-то, от чего дети будут в восторге. Секрет прост - это домашняя еда на природе.":
      "Atsevišķa komanda sagatavos kaut ko tādu, no kā bērni būs sajūsmā. Noslēpums ir vienkāršs — tā ir mājas ēdiens dabā.",
    "Любое культурно неприемлемое физическое, эмоциональное и любое другое воздействие на другого участника лагеря или на его вещи (подглядывать, трогать приватные части тела, проявлять любую сексуальную активность)":
      "Jebkāda kulturāli nepieņemama fiziska, emocionāla vai cita veida iedarbība uz citu nometnes dalībnieku vai viņa mantām (slepeni vērot, aiztikt privātās ķermeņa daļas, izrādīt jebkādu seksuālu aktivitāti)",
    "Мы заботимся о физической, эмоциональной и духовной безопасности каждого ребенка по заранее продуманным критериям (их более 100), в зонах ответственности по которым каждый сотрудник и участник проинструктирован и подписал договор.":
      "Mēs rūpējamies par katra bērna fizisko, emocionālo un garīgo drošību pēc iepriekš pārdomātiem kritērijiem (to ir vairāk nekā 100), atbildības zonās, par kurām katrs darbinieks un dalībnieks ir instruēts un parakstījis līgumu.",
    "Проверяться на клещей (мы напоминаем)": "Pārbaudīties, vai nav ērces (mēs atgādinām)",
    "Посмотреть на карте Google Maps": "Apskatīt Google Maps kartē",
    "Инструкции для навигатора Waze": "Norādes Waze navigācijai",
    "Наша цель - познакомить детей с Библией и Иисусом Христом на занятиях через интересные занятия.":
      "Mūsu mērķis ir iepazīstināt bērnus ar Bībeli un Jēzu Kristu caur interesantām nodarbībām.",
    "Летний лагерь - это прекрасная возможность вашим детям радостно и полезно отдохнуть на природе.":
      "Vasaras nometne ir lieliska iespēja jūsu bērniem priecīgi un lietderīgi atpūsties dabā.",
    "По приезду - подписание родителем согласия, что они осмотрели вещи и у ребенка с собой нет привезенных запрещенных вещей или веществ с собой":
      "Ierodoties — vecāka paraksts, ka viņi ir pārbaudījuši mantas un bērnam līdzi nav aizliegtu priekšmetu vai vielu",
    "Настоящие сокровища - это характер, который поможет приобрести все остальное":
      "Īstie dārgumi ir raksturs, kas palīdzēs iegūt visu pārējo",
    "Готовы зарегистрировать ребенка?": "Gatavi reģistrēt bērnu?",
