    "Информация для сотрудников лагеря Маранафа": "Informācija nometnes Maranafa darbiniekiem",
    "Стать сотрудником лагеря": "Kļūt par nometnes darbinieku",
    "Если вы хотите стать частью команды лагеря Маранафа, заполните анкету и отправьте ее нам. Мы свяжемся с вами для дальнейшего обсуждения.":
      "Ja vēlaties kļūt par Maranafa nometnes komandas daļu, aizpildiet anketu un nosūtiet to mums. Mēs ar jums sazināsimies, lai turpinātu apspriešanu.",
    "Требования к сотрудникам:": "Prasības darbiniekiem:",
